    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg and 0 < r < h-1 and 0 < c < w-1:
                out[r][c] = 4
    return out

